package ru.ryadom.calendar;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.CalendarContract;import org.json.*;import java.time.*;import java.util.*;
/** Read-only comparison of provider, cache and display. No titles, accounts or event IDs in output. */
final class DayDiagnostics {
 static boolean matches(String title,String query){return query.trim().isEmpty()||(title!=null&&title.toLowerCase(Locale.ROOT).contains(query.trim().toLowerCase(Locale.ROOT)));}
 static String report(Context c,LocalDate day,String query){
  JSONObject data=Store.read(c);long from=day.atStartOfDay(Event.ZONE).toInstant().toEpochMilli(),to=day.plusDays(1).atStartOfDay(Event.ZONE).toInstant().toEpochMilli();Map<String,int[]> counts=new TreeMap<>();Map<String,String> selected=new HashMap<>();Map<String,JSONObject> accounts=Mirror.accounts(data);StringBuilder out=new StringBuilder("Пекло "+BuildConfig.VERSION_NAME+" · диагностика дня\nДата МСК: "+day+"\nПоиск по названию: "+(query.trim().isEmpty()?"нет":"да (текст исключён)"));
  for(JSONObject a:accounts.values())if("device".equals(a.optString("type"))){JSONArray ids=a.optJSONArray("calendarIds");if(ids!=null)for(int i=0;i<ids.length();i++){String id=ids.optString(i);selected.put(id,a.optString("id"));counts.putIfAbsent(id,new int[5]);}}
  Uri.Builder uri=CalendarContract.Instances.CONTENT_URI.buildUpon();ContentUris.appendId(uri,from);ContentUris.appendId(uri,to);
  try(Cursor rows=c.getContentResolver().query(uri.build(),new String[]{"calendar_id","title","begin","end"},null,null,null)){
   if(rows==null)throw new IllegalStateException();while(rows.moveToNext()){if(rows.getLong(2)>=to||rows.getLong(3)<from||!matches(rows.getString(1),query))continue;counts.computeIfAbsent(rows.getString(0),k->new int[5])[0]++;}out.append("\nСистемные экземпляры: OK");
  }catch(Exception error){out.append("\nСистемные экземпляры: ").append(error.getClass().getSimpleName());}
  // Independent query detects non-recurring records absent from the Instances expansion.
  try(Cursor rows=c.getContentResolver().query(CalendarContract.Events.CONTENT_URI,new String[]{"calendar_id","title"},"deleted=0 AND dtstart>=? AND dtstart<? AND (rrule IS NULL OR rrule='') AND original_id IS NULL",new String[]{""+from,""+to},null)){
   if(rows==null)throw new IllegalStateException();while(rows.moveToNext())if(matches(rows.getString(1),query))counts.computeIfAbsent(rows.getString(0),k->new int[5])[4]++;out.append("\nОдиночные записи Events: OK");
  }catch(Exception error){out.append("\nОдиночные записи Events: ").append(error.getClass().getSimpleName());}
  Set<String> visible=new HashSet<>();for(Event e:Sync.visible(data,data.optBoolean("showCancelled")))visible.add(e.key());JSONArray cache=Store.array(data,"events");
  for(int i=0;i<cache.length();i++){Event e=Event.from(cache.optJSONObject(i));JSONObject account=accounts.get(e.source);if(account==null||!"device".equals(account.optString("type"))||!e.on(day)||!matches(e.title,query))continue;int[] row=counts.computeIfAbsent(e.calendar,k->new int[5]);row[1]++;if(Mirror.isCopy(data,e))row[2]++;if(visible.contains(e.key()))row[3]++;}
  out.append("\n\nID календаря | выбран | включён | чтение | Instances | Events* | кэш | копии | показано");
  for(Map.Entry<String,int[]> entry:counts.entrySet()){String cal=entry.getKey(),source=selected.get(cal);int[] n=entry.getValue();JSONObject status=source==null?null:Store.object(data,"statuses").optJSONObject(source);String state=source==null?"—":status==null?"не читался":!status.optString("error").isEmpty()?"ошибка":!accounts.get(source).optBoolean("active",true)?"остановлено":"OK";out.append("\n").append(cal).append(" | ").append(source==null?"нет":"да").append(" | ").append(source==null?"—":Store.object(data,"hidden").optBoolean(source+"|"+cal)?"нет":"да").append(" | ").append(state).append(" | ").append(n[0]).append(" | ").append(n[4]).append(" | ").append(n[1]).append(" | ").append(n[2]).append(" | ").append(n[3]);}
  out.append("\n\nEvents*: одиночные записи, начинающиеся в этот день; серии и переходящие встречи сюда не входят.\nКопии Пекла намеренно не показываются второй раз. Названия, адреса аккаунтов и ID встреч исключены. Ничего не изменено.");return out.toString();
 }
 static void show(MainActivity a){android.widget.LinearLayout box=a.column();box.setPadding(a.dp(20),0,a.dp(20),0);android.widget.EditText date=new android.widget.EditText(a),search=new android.widget.EditText(a);date.setSingleLine(true);date.setHint("ГГГГ-ММ-ДД");date.setText(a.day.toString());search.setSingleLine(true);search.setHint("Часть названия встречи (необязательно)");box.addView(date);box.addView(search);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(a).setTitle("Диагностика дня").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Проверить",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{LocalDate selected;try{selected=LocalDate.parse(date.getText().toString().trim());}catch(Exception error){date.setError("Формат: ГГГГ-ММ-ДД");return;}String query=search.getText().toString();dialog.getButton(-1).setEnabled(false);new Thread(()->{String text;try{text=report(a,selected,query);}catch(Exception error){text="Диагностика не завершилась: "+error.getClass().getSimpleName();}final String result=text;a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed())return;dialog.dismiss();new DeviceCalendarPicker(a).showReport(result);});},"day-diagnostics").start();}));dialog.show();}
}
